148	                // min: 0,
149	                nameTextStyle: iNameTextStyle,
150	                triggerEvent: triggerEvent
151	            } as InnerIndicatorAxisOption, false);
152	            if (zrUtil.isString(nameFormatter)) {
153	                const indName = innerIndicatorOpt.name;
